NONE_FOUND = 'v_pv_none_match="1";'


def fields(symbol: str, rows: Mapping[str, str] = ROWS, **changed: str) -> str:
    """The recorded row of ``symbol`` with some fields replaced (``f40='X'``): a variant for one test."""
    parts = rows[symbol].split('~')
    for key, value in changed.items():
        parts[int(key[1:])] = value
    return '~'.join(parts)


def answer(symbols: Iterable[str], rows: Optional[Mapping[str, str]] = None) -> bytes:
    """The body Tencent sends for ``symbols``: a statement for each one ``rows`` holds, GBK-encoded."""
    rows = ROWS if rows is None else rows
    lines = [f'v_{symbol}="{rows[symbol]}";' for symbol in symbols if symbol in rows]
    return ('\n'.join(lines) + '\n' if lines else NONE_FOUND + '\n').encode('gbk')
